#![allow(unused_imports)]
use vstd::prelude::*;

verus! {

fn nanmin(a: Vec<i8>) -> (result: i8)
    requires
        a.len() > 0,
    ensures
        // result is an element of the array
        exists|k: int| 0 <= k < a.len() && result == a[k],
        // result is <= every element
        forall|k: int| 0 <= k < a.len() ==> result <= a[k],
{
    let mut min = a[0];
    let mut i: usize = 1;

    while i < a.len()
        invariant
            1 <= i <= a.len(),
            // min is some element among a[0..i)
            exists|k: int| 0 <= k < i as int && min == a[k],
            // min is <= all elements among a[0..i)
            forall|k: int| 0 <= k < i as int ==> min <= a[k],
        decreases
            a.len() - i,
    {
        if a[i] < min {
            min = a[i];
        }
        i += 1;
    }

    // Conclude the postconditions from the loop invariants at i == a.len().
    assert(i == a.len());
    assert(exists|k: int| 0 <= k < a.len() && min == a[k]);
    assert(forall|k: int| 0 <= k < a.len() ==> min <= a[k]);

    min
}

} // verus!